import * as T from 'three';
import {OBB} from './vendor/OBB.js';
import {PINS} from './electrical.js';
export const palette={dark:0x222c34,rubber:0x10161b,metal:0xaab6bf,orange:0xed842a,white:0xcbd3ce,gold:0xc6a35c};
export const material=(color,metalness=0,roughness=.6)=>new T.MeshStandardMaterial({color,metalness,roughness});
export function box(parent,w,h,d,color,x=0,y=0,z=0,solid=true){const mesh=new T.Mesh(new T.BoxGeometry(w,h,d),typeof color==='number'?material(color):color);mesh.position.set(x,y,z);mesh.castShadow=true;mesh.receiveShadow=true;parent.add(mesh);if(solid)mesh.userData.solid=new T.Vector3(w/2,h/2,d/2);return mesh;}
export function cylinder(parent,radius,length,color,x=0,y=0,z=0){const m=new T.Mesh(new T.CylinderGeometry(radius,radius,length,36),typeof color==='number'?material(color):color);m.rotation.x=Math.PI/2;m.userData.solid=new T.Vector3(radius,length/2,radius);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m;}
export function textTexture(text,{bg='#152733',fg='#d7e4ea',size=40,width=1024,height=128}={}){const c=document.createElement('canvas');c.width=width;c.height=height;const ctx=c.getContext('2d');ctx.fillStyle=bg;ctx.fillRect(0,0,width,height);ctx.fillStyle=fg;ctx.font=`600 ${size}px Arial`;ctx.textAlign='center';ctx.textBaseline='middle';String(text).split('\n').forEach((line,i,lines)=>ctx.fillText(line,width/2,height/2+(i-(lines.length-1)/2)*(size+10)));const tx=new T.CanvasTexture(c);tx.colorSpace=T.SRGBColorSpace;return tx;}
export function label(parent,text,w,h,pos,options={}){const tx=textTexture(text,options);const m=new T.Mesh(new T.PlaneGeometry(w,h),new T.MeshBasicMaterial({map:tx,side:T.DoubleSide,transparent:false}));m.position.copy(pos);parent.add(m);m.userData.setText=t=>{m.material.map.dispose();m.material.map=textTexture(t,options);};return m;}
export function colliderOf(mesh){mesh.updateWorldMatrix(true,false);const pos=new T.Vector3(),q=new T.Quaternion(),scale=new T.Vector3();mesh.matrixWorld.decompose(pos,q,scale);return new OBB(pos,mesh.userData.solid.clone().multiply(scale),new T.Matrix3().setFromMatrix4(new T.Matrix4().makeRotationFromQuaternion(q)));}
export function pinsLayout(kind){if(['screen','orange'].includes(kind)){const a=[];for(let i=0;i<6;i++){a.push({n:6-i,x:(i-2.5)*.215,y:.2});a.push({n:7+i,x:(i-2.5)*.215,y:-.2});}if(kind==='orange')a.forEach(p=>p.x*=-1);return a;}
 if(['up4','low4'].includes(kind)){return(kind==='up4'?[4,1,3,2]:[1,4,2,3]).map((n,i)=>({n,x:i%2? .155:-.155,y:i<2?.155:-.155}));}
 const a=[{n:8,x:-.13,y:.34},{n:1,x:.13,y:.34},{n:7,x:-.34,y:.115},{n:12,x:-.17,y:0},{n:9,x:0,y:.17},{n:2,x:.34,y:.115},{n:6,x:-.34,y:-.115},{n:10,x:0,y:-.17},{n:11,x:.17,y:0},{n:3,x:.34,y:-.115},{n:5,x:-.13,y:-.34},{n:4,x:.13,y:-.34}];if(kind==='circular')a.forEach(p=>p.x*=-1);return a;}
export function makePort(part,kind,id,pos,rot,scene){const group=new T.Group();group.position.copy(pos);if(rot)group.quaternion.copy(rot);const port={id,kind,part,group,pins:[],colliders:[],mate:null,blockMate:null};group.userData.port=port;part.ports.push(port);scene.add(group);const main=['screen','orange'].includes(kind),four=['up4','low4'].includes(kind),male=['screen','low4','em'].includes(kind);const w=main?1.57:four?.79:1.12,h=main?.78:four?.79:1.12;const shell=main?(male?palette.dark:palette.orange):four?palette.white:palette.rubber;
 if(main||four){const bevel=new T.Shape();const b=four?.12:.07;bevel.moveTo(-w/2,-h/2);bevel.lineTo(w/2-b,-h/2);bevel.lineTo(w/2,-h/2+b);bevel.lineTo(w/2,h/2);bevel.lineTo(-w/2,h/2);bevel.closePath();const extr=new T.Mesh(new T.ExtrudeGeometry(bevel,{depth:.14,bevelEnabled:false}),material(shell));if(kind==='low4'||kind==='orange')extr.scale.x=-1;extr.position.z=-.3;group.add(extr);extr.castShadow=true;
 box(group,w,h,.16,shell,0,0,-.22);box(group,.085,h,.45,shell,-w/2+.042,0,-.035);box(group,.085,h,.45,shell,w/2-.042,0,-.035);box(group,w,.085,.45,shell,0,h/2-.042,-.035);box(group,w,.085,.45,shell,0,-h/2+.042,-.035);
 if(main){box(group,1.13,.105,.2,palette.dark,0,0,-.065);for(const side of [-1,1]){const latch=box(group,.11,.35,.19,palette.metal,side*(w/2+.03),0,-.12);latch.userData.latch=port;}}else{box(group,.075,h-.1,.28,shell,0,0,-.04);box(group,w-.1,.075,.28,shell,0,0,-.04);const key=box(group,.13,.13,.3,shell,(kind==='low4'?-1:1)*(w/2-.1),-h/2+.1,-.04);key.rotation.z=Math.PI/4;const latch=box(group,.27,.115,.36,palette.white,0,h/2+.055,-.06);latch.userData.latch=port;}
 }else{cylinder(group,.535,.15,palette.rubber,0,0,-.24);box(group,.75,.75,.14,palette.rubber,0,0,-.25);const ring=new T.Group();group.add(ring);port.ring=ring;const tor=new T.Mesh(new T.TorusGeometry(.51,.08,10,48),material(male?palette.dark:palette.rubber));ring.add(tor);for(let i=0;i<20;i++){const a=i/20*Math.PI*2;const m=box(ring,.13,.08,.32,palette.dark,Math.cos(a)*.51,Math.sin(a)*.51,-.08);m.rotation.z=a+Math.PI/2;}box(group,.13,.15,.29,palette.rubber,0,.41,-.015);}
 for(const p of pinsLayout(kind)){const metal=cylinder(group,male?.038:.059,male?.21:.065,male?palette.gold:palette.dark,p.x,p.y,male?-.005:.02);if(!male){const rim=new T.Mesh(new T.TorusGeometry(.045,.011,6,16),material(palette.gold,.5,.35));rim.position.set(p.x,p.y,.055);group.add(rim);}metal.userData.pin={port,n:p.n};metal.userData.tooltip=()=>PINS[kind][p.n]?`${p.n} · ${PINS[kind][p.n]}`:'';port.pins.push(metal);const hit=new T.Mesh(new T.SphereGeometry(.075,8,8),new T.MeshBasicMaterial({transparent:true,opacity:0,depthWrite:false}));hit.position.set(p.x,p.y,.09);hit.userData.pin={port,n:p.n};group.add(hit);
 if(PINS[kind][p.n])label(group,String(p.n),.095,.07,new T.Vector3(p.x,p.y+(p.y>=0?.095:-.095),.125),{bg:main&&!male?'#ed842a':four?'#cbd3ce':'#222c34',fg:four||main&&!male?'#17212a':'#e3e9ee',width:64,height:48,size:34});}
 group.traverse(m=>{if(m.userData.solid){m.userData.port=port;port.colliders.push(m);}});return port;}
export function cable(points,color,radius=.085){const c=new T.CatmullRomCurve3(points);const mesh=new T.Mesh(new T.TubeGeometry(c,30,radius,8,false),material(color));mesh.castShadow=true;return mesh;}
